export interface AdultClock { now(): string; }
export class LocalAdultClock implements AdultClock { private value: string; constructor(initial: string) { this.value = iso(initial, "ADULT_TIME_INVALID"); } now(): string { return this.value; } advance(nextInput: unknown): void { const next = iso(nextInput, "ADULT_TIME_INVALID"); if (Date.parse(next) < Date.parse(this.value)) fail("ADULT_TIME_ROLLBACK"); this.value = next; } }
